-- GENERATED by scripts/gen-suites.mjs from registry/db-schema.json — AP Supplier application (SM: registration, add category, update, renewal, cancel …). READ-ONLY queries for DBeaver, SIT connection only.
-- Replace {NO} with the document number (e.g. AP26…). Mapping verified: yes — SIT 2026-11-23: SM_WORKFLOW_STATUS has only doc_type SR, doc_id = SM_APPL.APPL_ID; KN-06112026-0050 → 20100, 20101, 20104, 20105, 20108. Prefixes: KN/JN new, KA/JA add category, KU/JU update, KB bumiputera, KR/JR renewal, KC/JC cancel (K = contractor, J = consultant)

-- Status history (SR); the row with is_current = 1 is the current status
select w.doc_type, w.status_id, w.is_current, to_char(w.created_date, 'YYYY-MM-DD HH24:MI:SS') as changed_at,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.sm_workflow_status w
 where w.doc_type = 'SR'
   and w.doc_id in (select appl_id from ngep_sit.sm_appl where appl_no = '{NO}')
 order by w.created_date, w.workflow_status_id;

-- Open BPM tasks: who the task is assigned to (task name = activityname)
select activityname, state, assignees, acquiredby, to_char(createddate, 'YYYY-MM-DD HH24:MI:SS') as created
  from SIT01_SOAINFRA.wftask@SITSOA
 where customattributestring1 = '{NO}'
 order by createddate;

-- Every status a SR has used on SIT in the last year (EN/BM), to see where a document can stop
select w.status_id, count(*) as rows_,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.sm_workflow_status w
 where w.doc_type = 'SR' and w.created_date > sysdate - 365
 group by w.status_id order by w.status_id;
